            {if ui_is_set_str(ui_field($item, 'Href', ''))} href="{=ui_field($item, 'Href', '')|nocheck}"{/if}
            class="{=ui_cn(['text-sm', (ui_field($item, 'Current', false) ? 'font-medium' : (ui_field($item, 'Disabled', false) ? 'text-muted-foreground' : 'text-primary underline-offset-4 hover:underline'))])}"
            {if ui_field($item, 'Current', false)} aria-current="page"{/if}
          >{=ui_field($item, 'Label', '')}</a>
        {else}
          <span
            class="{=ui_cn(['text-sm', (ui_field($item, 'Current', false) ? 'font-medium' : (ui_field($item, 'Disabled', false) ? 'text-muted-foreground' : 'text-primary underline-offset-4 hover:underline'))])}"
            {if ui_field($item, 'Current', false)} aria-current="page"{/if}
          >{=ui_field($item, 'Label', '')}</span>
        {/if}
      </li>
    {/foreach}
  </ol>
</nav>
